class PrimeGenerator implements Runnable { private static final Object __auxLock = new Object(); 
    private boolean cancelled;   // guarded by "this"
    private final List<BigInteger> primes = Collections.synchronizedList(new ArrayList<>());
    private final ExecutorService executor = Executors.newFixedThreadPool(1);

    private synchronized boolean isCancelled() { synchronized (__auxLock) { 
        return cancelled;
     } }

    private void setCancelled() { synchronized (__auxLock) { synchronized (this) { 
        cancelled = true;
     } } }

    public void run() {
        BigInteger current = BigInteger.ONE;
